                        text = v
                        break
        if not text and isinstance(response, str):
            text = response
    if not text:
        text = str(a)
    if len(items) > 1:
        combined += f"# Source {i + 1}\n\n{text}\n\n---\n\n"
    else:
        combined += text

result: str = combined

