grouped_results: list

import re

choruses = []
for gr in grouped_results:
    response = gr.get("response", "") if isinstance(gr, dict) else str(gr)
    item = gr.get("item", {}) if isinstance(gr, dict) else {}
    model = item.get("model", "unknown")

    parts = re.split(r'===CHORUS \d+:\s*([^=]+)===', response)
    i = 1
    while i < len(parts) - 1:
        lens_name = parts[i].strip()
        lyrics = parts[i + 1].strip()
        if lyrics:
            choruses.append({
                "chorus_text": lyrics,
                "lens": lens_name.lower().replace(" ", "-"),
                "model": model
            })
        i += 2

result: list = choruses

reviews: list

review_labels = {
    "emotional-architecture": "Emotional Architecture",
    "narrative": "Narrative Arc",
    "imagery": "Imagery Quality",
    "stranger-summary": "Stranger Summary (Legibility)"
}

sections = []
for review in reviews:
    if isinstance(review, dict):
        focus = "unknown"
        item = review.get("item", {})
        if isinstance(item, dict):
            focus = item.get("focus", "unknown")
        label = review_labels.get(focus, focus)
        response = review.get("review_text", review.get("response", str(review)))
        sections.append(f"## {label}\n\n{response}")
    else:
        sections.append(str(review))

result: str = "\n\n---\n\n".join(sections)

